define("local_th_qaa_manager/load_courses",["jquery","core/ajax","core/str"],(function($,Ajax,Str){return{transport:function(selector,query,success,failure){Ajax.call([{methodname:"local_th_qaa_manager_load_courses",args:{term:query}}])[0].then((function(response){response&&response.length?response.length>100?Str.get_string("toomanycoursetoshow","report_th_gradebook_export",">100").then((function(msg){success([{value:null,label:'<div style="pointer-events:none;">'+msg+"</div>"}])})).catch((function(){success(response)})):success(response):success([])})).fail(failure)},processResults:function(selector,results){const courses=[];return Array.isArray(results)&&results.forEach((function(course){courses.push(course)})),courses}}}));
